-- =============================================
-- 91. 기출 문제 은행 — 문법 영역의 남은 빈 태그 (문법 지문에 붙은 문항 · 지문 없는 문항)
-- 실행: node /Users/ara/Projects/Ara-system/scripts/run-sql.js sql/91_problem_bank_grammar_tags_rest.sql
-- =============================================
-- 배경(원장님 2026-11-06): "남은 일도 전부 다 해." sql/87·90 뒤에도 영역이 `화법과 언어 > 언어` 인데 태그가 빈 문항이 남아 있었다
-- (업체본 적재 때 달지 않았다). 코덱스가 문항을 읽어 정했고 규칙은 sql/87 머리말과 같다.
--
-- ⚠️ 문법·어휘·어문 규정·담화·국어사 어디에도 안 드는 문항(영역이 잘못 든 문학 용어·작문·매체 내용)은 비워 두었다.
-- ⚠️ 읽고 정한 값이라 재계산할 수 없다. 지금 태그가 빈 문항만 채운다. 판정 기록(decisions-final.json)과 스펙에도 같은 값이다.

BEGIN;

SET LOCAL search_path = exam, public;

CREATE TEMP TABLE _tags (
  id    UUID PRIMARY KEY,
  paths TEXT[] NOT NULL,
  note  TEXT NOT NULL
) ON COMMIT DROP;


DO $tags$
DECLARE
  v_total INT;
  v_done  INT;
  v_bad   INT;
BEGIN
  IF to_regclass('exam.problems') IS NULL THEN
    RAISE EXCEPTION 'exam.problems 가 없습니다 (현재 DB: %).', current_database();
  END IF;
  SELECT count(*) INTO v_total FROM _tags;

  UPDATE exam.problems p SET grammar_paths = t.paths
    FROM _tags t WHERE p.id = t.id AND cardinality(p.grammar_paths) = 0;
  GET DIAGNOSTICS v_done = ROW_COUNT;
  RAISE NOTICE '태그 단 문항 % / 이미 값이 있어 건너뜀 % (목록 %)', v_done, v_total - v_done, v_total;

  -- 검증 — 태그가 빈 채 남은 것이 없는가
  SELECT count(*) INTO v_bad FROM _tags t JOIN exam.problems p ON p.id = t.id WHERE cardinality(p.grammar_paths) = 0;
  IF v_bad > 0 THEN RAISE EXCEPTION '태그가 빈 문항 %건이 남았습니다.', v_bad; END IF;
END
$tags$;

SELECT exam.archive_facets_refresh();

COMMIT;
